mapper.sql:
WITH , execution_enriched AS ( SELECT , eb.EXIT_CODE AS exit_code, cs.step_status, eb.EXIT_MESSAGE AS exit_message,
AS transfer_error_message
), latest_batch AS ( SELECT ee.*, ROW_NUMBER() OVER ( PARTITION BY ee.batch_id ORDER BY ee.sort_time DESC, ee.execution_id DESC ) AS rn FROM execution_enriched ee )

mapper.select:
, selected_batch AS ( SELECT lb.* FROM latest_batch lb WHERE lb.rn = 1 AND lb.batch_id = #{batchId}
) SELECT sb.execution_id AS execution_id, je.JOB_INSTANCE_ID AS job_instance_id, AS job_name, AS job_status, AS job_exit_code, AS job_exit_message, AS job_create_time, AS job_start_time, AS job_end_time, sb.duration_ms AS job_duration_ms, sb.task_id AS task_id, sb.file_id AS file_id, ( SELECT FROM BATCH_JOB_EXECUTION_PARAMS jp WHERE jp.JOB_EXECUTION_ID = sb.execution_id AND = 'businessKey'
) AS business_key, ( SELECT FROM BATCH_JOB_EXECUTION_PARAMS jp WHERE jp.JOB_EXECUTION_ID = sb.execution_id AND = 'taskType'
) AS task_type, sb.task_stage AS task_stage, sb.input_payload AS input_payload, pq.queue_id AS queue_id, AS queue_status, AS queue_delivery_status, AS queue_trigger_mode, pq.retry_count AS queue_retry_count, AS queue_claimed_by, AS queue_claimed_at, AS queue_parsed_at, AS queue_error_message, AS queue_request_json, AS queue_result_json, AS transfer_id, AS transfer_status, ( SELECT FROM t_transfer_delivery_record tdr WHERE tdr.transfer_id = tto.transfer_id ORDER BY tdr.delivered_at DESC, tdr.delivery_id DESC
) AS delivery_execute_status, ( SELECT FROM t_transfer_delivery_record tdr WHERE tdr.transfer_id = tto.transfer_id ORDER BY tdr.delivered_at DESC, tdr.delivery_id DESC
) AS delivery_delivered_at, ( SELECT FROM t_transfer_delivery_record tdr WHERE tdr.transfer_id = tto.transfer_id ORDER BY tdr.delivered_at DESC, tdr.delivery_id DESC
) AS delivery_error_message, AS transfer_source_type, AS transfer_source_code, AS transfer_original_name, AS transfer_received_at, AS transfer_stored_at, AS transfer_business_date, AS transfer_error_message FROM selected_batch sb LEFT JOIN BATCH_JOB_EXECUTION je ON je.JOB_EXECUTION_ID = sb.execution_id LEFT JOIN BATCH_JOB_INSTANCE ji ON ji.JOB_INSTANCE_ID = je.JOB_INSTANCE_ID LEFT JOIN t_transfer_object tto ON tto.transfer_id = sb.file_id LEFT JOIN t_parse_queue pq ON pq.transfer_id = tto.transfer_id
